import { randomBytes, randomUUID } from 'node:crypto';
import { readFile, rename, writeFile } from 'node:fs/promises';

import { DB_PATH, ensureRuntimeDirectories } from './config.js';
import type { Chat, MediaFile, Message, Session, User } from './types.js';

interface StoredUser extends User {
  passwordHash: string;
}

interface Database {
  users: StoredUser[];
  chats: Chat[];
  messages: Message[];
  sessions: Session[];
  media: MediaFile[];
  lastRead: Record<string, string>;
}

export interface CreateUserInput {
  username: string;
  passwordHash: string;
  displayName: string;
  avatarColor: string;
}

export interface CreateChatInput {
  type: Chat['type'];
  memberIds: string[];
  title?: string | null;
}

export interface CreateMessageInput {
  chatId: string;
  senderId: string;
  type: Message['type'];
  text?: string | null;
  audioId?: string | null;
  audioDurationMs?: number | null;
}

export interface SaveMediaInput {
  path: string;
  mime: string;
  size: number;
}

const emptyDatabase = (): Database => ({
  users: [], chats: [], messages: [], sessions: [], media: [], lastRead: {},
});

let database: Database;
let writeQueue: Promise<void> = Promise.resolve();

const ready = (async (): Promise<void> => {
  await ensureRuntimeDirectories();
  try {
    const parsed = JSON.parse(await readFile(DB_PATH, 'utf8')) as Partial<Database>;
    database = {
      users: parsed.users ?? [],
      chats: parsed.chats ?? [],
      messages: parsed.messages ?? [],
      sessions: parsed.sessions ?? [],
      media: parsed.media ?? [],
      lastRead: parsed.lastRead ?? {},
    };
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
    database = emptyDatabase();
    await persist();
  }
})();

function publicUser(user: StoredUser): User {
  return {
    id: user.id,
    username: user.username,
    displayName: user.displayName,
    avatarColor: user.avatarColor,
    createdAt: user.createdAt,
  };
}

async function persist(): Promise<void> {
  const temporaryPath = `${DB_PATH}.${process.pid}.tmp`;
  await writeFile(temporaryPath, `${JSON.stringify(database, null, 2)}\n`, 'utf8');
  await rename(temporaryPath, DB_PATH);
}

async function mutate<T>(operation: () => T | Promise<T>): Promise<T> {
  await ready;
  const result = writeQueue.then(async () => {
    const value = await operation();
    await persist();
    return value;
  });
  writeQueue = result.then(() => undefined, () => undefined);
  return result;
}

function lastReadKey(chatId: string, userId: string): string {
  return `${chatId}:${userId}`;
}

export class UsernameTakenError extends Error {
  constructor() {
    super('username_taken');
    this.name = 'UsernameTakenError';
  }
}

export async function getUserById(id: string): Promise<User | null> {
  await ready;
  const user = database.users.find((candidate) => candidate.id === id);
  return user ? publicUser(user) : null;
}

export async function getUserByUsername(username: string): Promise<StoredUser | null> {
  await ready;
  const normalized = username.toLocaleLowerCase('en-US');
  return database.users.find(
    (candidate) => candidate.username.toLocaleLowerCase('en-US') === normalized,
  ) ?? null;
}

export async function createUser(input: CreateUserInput): Promise<User> {
  return mutate(() => {
    const normalized = input.username.toLocaleLowerCase('en-US');
    if (database.users.some(
      (candidate) => candidate.username.toLocaleLowerCase('en-US') === normalized,
    )) throw new UsernameTakenError();

    const user: StoredUser = {
      id: randomUUID(),
      username: input.username,
      passwordHash: input.passwordHash,
      displayName: input.displayName,
      avatarColor: input.avatarColor,
      createdAt: new Date().toISOString(),
    };
    database.users.push(user);
    return publicUser(user);
  });
}

export async function createSession(userId: string): Promise<string> {
  return mutate(() => {
    const token = randomBytes(32).toString('hex');
    database.sessions.push({ token, userId, createdAt: new Date().toISOString() });
    return token;
  });
}

export async function getSession(token: string): Promise<Session | null> {
  await ready;
  return database.sessions.find((session) => session.token === token) ?? null;
}

export async function deleteSession(token: string): Promise<void> {
  await mutate(() => {
    database.sessions = database.sessions.filter((session) => session.token !== token);
  });
}

export async function listUsers(options: { q?: string; excludeId?: string } = {}): Promise<User[]> {
  await ready;
  const query = options.q?.trim().toLocaleLowerCase('en-US') ?? '';
  return database.users
    .filter((user) => user.id !== options.excludeId)
    .filter((user) => !query
      || user.username.toLocaleLowerCase('en-US').includes(query)
      || user.displayName.toLocaleLowerCase('en-US').includes(query))
    .map(publicUser);
}

export async function listChatsForUser(userId: string): Promise<Chat[]> {
  await ready;
  return database.chats
    .filter((chat) => chat.memberIds.includes(userId))
    .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt));
}

export async function getChatById(id: string): Promise<Chat | null> {
  await ready;
  return database.chats.find((chat) => chat.id === id) ?? null;
}

export async function findDirectChat(userA: string, userB: string): Promise<Chat | null> {
  await ready;
  return database.chats.find((chat) => chat.type === 'direct'
    && chat.memberIds.length === 2
    && chat.memberIds.includes(userA)
    && chat.memberIds.includes(userB)) ?? null;
}

export async function createChat(input: CreateChatInput): Promise<Chat> {
  return mutate(() => {
    const now = new Date().toISOString();
    const chat: Chat = {
      id: randomUUID(),
      type: input.type,
      title: input.title ?? null,
      memberIds: [...new Set(input.memberIds)],
      createdAt: now,
      updatedAt: now,
    };
    database.chats.push(chat);
    return chat;
  });
}

export async function touchChat(chatId: string): Promise<Chat | null> {
  return mutate(() => {
    const chat = database.chats.find((candidate) => candidate.id === chatId);
    if (!chat) return null;
    chat.updatedAt = new Date().toISOString();
    return chat;
  });
}

export async function listMessages(
  chatId: string,
  options: { before?: string; limit?: number } = {},
): Promise<Message[]> {
  await ready;
  const limit = Math.max(1, Math.min(options.limit ?? 50, 100));
  let messages = database.messages
    .filter((message) => message.chatId === chatId)
    .sort((left, right) => left.createdAt.localeCompare(right.createdAt));
  if (options.before) {
    const cursorIndex = messages.findIndex((message) => message.id === options.before);
    messages = cursorIndex >= 0
      ? messages.slice(0, cursorIndex)
      : messages.filter((message) => message.createdAt < options.before!);
  }
  return messages.slice(-limit);
}

export async function createMessage(input: CreateMessageInput): Promise<Message> {
  return mutate(() => {
    const message: Message = {
      id: randomUUID(),
      chatId: input.chatId,
      senderId: input.senderId,
      type: input.type,
      text: input.text ?? null,
      audioId: input.audioId ?? null,
      audioDurationMs: input.audioDurationMs ?? null,
      createdAt: new Date().toISOString(),
      status: 'sent',
    };
    database.messages.push(message);
    const chat = database.chats.find((candidate) => candidate.id === input.chatId);
    if (chat) chat.updatedAt = message.createdAt;
    return message;
  });
}

export async function updateMessageStatus(
  id: string,
  status: Message['status'],
): Promise<Message | null> {
  return mutate(() => {
    const message = database.messages.find((candidate) => candidate.id === id);
    if (!message) return null;
    message.status = status;
    return message;
  });
}

export async function getUnreadCount(
  chatId: string,
  userId: string,
  lastReadId?: string | null,
): Promise<number> {
  await ready;
  const messages = database.messages
    .filter((message) => message.chatId === chatId)
    .sort((left, right) => left.createdAt.localeCompare(right.createdAt));
  const cursor = lastReadId ?? database.lastRead[lastReadKey(chatId, userId)];
  const cursorIndex = cursor ? messages.findIndex((message) => message.id === cursor) : -1;
  return messages.slice(cursorIndex + 1).filter((message) => message.senderId !== userId).length;
}

export async function setLastRead(
  chatId: string,
  userId: string,
  messageId: string,
): Promise<void> {
  await mutate(() => {
    database.lastRead[lastReadKey(chatId, userId)] = messageId;
  });
}

export async function saveMedia(input: SaveMediaInput): Promise<MediaFile> {
  return mutate(() => {
    const media: MediaFile = {
      id: randomUUID(),
      path: input.path,
      mime: input.mime,
      size: input.size,
      createdAt: new Date().toISOString(),
    };
    database.media.push(media);
    return media;
  });
}

export async function getMedia(id: string): Promise<MediaFile | null> {
  await ready;
  return database.media.find((media) => media.id === id) ?? null;
}
